import asyncio
import json
from app.core.logging import get_logger
from sqlalchemy import text
from sqlalchemy.ext.asyncio import AsyncSession

logger = get_logger(__name__)


async def seed_ai_curriculum(session: AsyncSession = None):
    from app.core.database import async_session_maker

    if session is None:
        async with async_session_maker() as session:
            return await _do_seed(session)
    else:
        return await _do_seed(session)


async def _do_seed(db: AsyncSession):
    # Idempotency check
    r = await db.execute(text("SELECT COUNT(*) FROM courses WHERE title = 'AI for the Exhausted'"))
    if r.scalar() > 0:
        logger.info("AI curriculum already seeded, skipping")
        return

    logger.info("Seeding AI training curriculum...")

    # Helper to insert and get ID
    async def insert_course(title, description, access_level, difficulty, estimated_minutes, sensory_warning, xp_reward):
        await db.execute(text("""
            INSERT INTO courses (title, description, access_level, difficulty, estimated_minutes, sensory_warning, xp_reward, lifecycle_stage)
            VALUES (:t, :d, :al, :diff, :em, :sw, :xp, 'published')
        """), {"t": title, "d": description, "al": access_level, "diff": difficulty, "em": estimated_minutes, "sw": sensory_warning, "xp": xp_reward})
        r = await db.execute(text("SELECT id FROM courses WHERE title = :t"), {"t": title})
        return r.scalar()

    async def insert_module(course_id, title, description, sort_order):
        await db.execute(text("""
            INSERT INTO modules (course_id, title, description, sort_order)
            VALUES (:cid, :t, :d, :so)
        """), {"cid": course_id, "t": title, "d": description, "so": sort_order})
        r = await db.execute(text("SELECT id FROM modules WHERE course_id = :cid AND sort_order = :so"), {"cid": course_id, "so": sort_order})
        return r.scalar()

    async def insert_lesson(module_id, title, lesson_type, content, estimated_minutes, xp_reward, sort_order):
        await db.execute(text("""
            INSERT INTO lessons (module_id, title, lesson_type, content, estimated_minutes, xp_reward, sort_order)
            VALUES (:mid, :t, :lt, :c, :em, :xp, :so)
        """), {"mid": module_id, "t": title, "lt": lesson_type, "c": json.dumps(content), "em": estimated_minutes, "xp": xp_reward, "so": sort_order})
        r = await db.execute(text("SELECT id FROM lessons WHERE module_id = :mid AND sort_order = :so"), {"mid": module_id, "so": sort_order})
        return r.scalar()

    async def insert_quiz(lesson_id, question_text, options, explanation, sort_order):
        await db.execute(text("""
            INSERT INTO quiz_questions (lesson_id, question_text, question_type, options, explanation, sort_order)
            VALUES (:lid, :qt, 'multiple_choice', :opts, :exp, :so)
        """), {"lid": lesson_id, "qt": question_text, "opts": json.dumps(options), "exp": explanation, "so": sort_order})

    # ================================================================
    # COURSE 1: AI for the Exhausted
    # ================================================================
    c1 = await insert_course(
        "AI for the Exhausted",
        "The entry point for skeptical, tired staff. This isn't about learning AI -- this is about making one annoying task disappear. Two hands-on sessions that start with your real work and end with a staff-authored AI use policy.",
        "staff", "beginner", 240,
        "Group activities involve verbal sharing (voluntary). Sticky note exercises require writing. No flashing screens or sudden audio.",
        200
    )

    # Session 1: The One Thing
    m1_1 = await insert_module(c1, "Session 1: The One Thing", "Identify one real task, use AI to do it, evaluate the result. Two hours of hands-on work with zero jargon.", 0)

    await insert_lesson(m1_1, "The Sticky Note Exercise", "lab", {"body": "# The Sticky Note Exercise\n\n## Setup\nEach person gets a sticky note and a marker.\n\n## The Task\nWrite down **one task you hate doing at work.** Not the hardest task. Not the most important. The one that makes you groan.\n\nExamples from past sessions:\n- Writing social media posts for programs\n- Drafting the monthly newsletter blurb\n- Summarizing meeting notes\n- Writing catalog descriptions for new materials\n- Composing emails to community partners\n\n## The Grouping\nStick your note on the wall. Group them by similarity:\n- **Writing** (posts, emails, blurbs, descriptions)\n- **Scheduling** (calendars, room bookings, program planning)\n- **Data entry** (statistics, reports, forms)\n- **Communication** (emails, phone scripts, signage)\n\n## The Vote\nEveryone gets one dot sticker. Place it on the category you most want to solve today.\n\n## The Frame\n> \"We're not learning AI today. We're firing a vendor called 'tedious work.'\""}, 15, 15, 0)

    await insert_lesson(m1_1, "The Demo: One Prompt, One Task", "article", {"body": "# The Demo\n\nThe facilitator opens the local LLM (already running -- no setup, no logins, no accounts).\n\n## One Prompt\nType exactly this:\n\n> Write 5 Facebook posts for next week's storytime program. The theme is ocean animals. Our library is open Tuesday-Saturday. Storytime is Wednesday at 10:30 AM for ages 3-5.\n\n## What Happens\n- The AI generates 5 posts in seconds\n- Display the raw output on screen\n- Don't edit it. Don't clean it up. Show it exactly as it comes out.\n\n## What to Notice\n- How fast was that?\n- Does it sound like your library?\n- What did it get right?\n- What sounds like a robot wrote it?\n\n## Key Point\nThis is the starting material, not the finished product. Nobody's posting this as-is."}, 10, 10, 1)

    await insert_lesson(m1_1, "The Comparison: Human vs. Machine", "lab", {"body": "# The Comparison\n\n## Your Turn (5 minutes)\nWrite your own version of the same task the AI just did. Use whatever the group voted on -- social media posts, newsletter blurbs, emails, whatever it was.\n\nSet a timer. Five minutes. Go.\n\n## Side by Side (10 minutes)\nPut your version next to the AI's version. Compare on these criteria:\n\n| Criteria | Your Version | AI Version |\n|----------|-------------|------------|\n| **Accuracy** | Does it have the right details? | Does it have the right details? |\n| **Voice** | Does it sound like your library? | Does it sound like your library? |\n| **Tone** | Would a patron recognize this as yours? | Would a patron recognize this as yours? |\n| **Time** | How long did it take? | How long did it take? |\n\n## Discussion Prompts\n- What did the AI get right that surprised you?\n- What did it miss that seems obvious to you?\n- What sounds like a robot wrote it?\n- Would you be comfortable posting the AI version? Why or why not?"}, 15, 20, 2)

    await insert_lesson(m1_1, "The Edit: Shaping the Clay", "lab", {"body": "# The Edit\n\n## The Task\nTake the AI's **worst** draft -- the one that sounds most robotic, most generic, most not-you.\n\nRewrite it in your voice. Keep what works. Fix what doesn't. Add what's missing.\n\n## Time\n10 minutes for rewriting. Then share one rewrite with the group.\n\n## What to Notice While Editing\n- How much did you change? A few words? Whole sentences? Everything?\n- What did you keep? What was actually useful?\n- Was it faster to edit the AI's draft than to write from scratch?\n\n## The Key Insight\n> \"The AI isn't replacing you. It's giving you clay to shape.\"\n\nYou're still the potter. The AI just saved you the trip to dig up the clay.\n\n## Share\nRead your rewrite aloud (or pass it to a neighbor if reading aloud isn't your thing). One sentence about what you changed and why."}, 20, 25, 3)

    await insert_lesson(m1_1, "The Expansion: Iteration Is Instant", "sandbox", {"body": "# The Expansion\n\nNow try the same task with different angles. Same base prompt, different instructions:\n\n## Try These Variations\n1. **\"Make it funnier.\"** -- Does humor help or hurt?\n2. **\"Make it shorter. Maximum 2 sentences.\"** -- Can it be concise?\n3. **\"Write it for grandparents, not parents.\"** -- Can it shift audience?\n4. **\"Add a call-to-action about library card signups.\"** -- Can it layer in goals?\n5. **\"Write it in Spanish.\"** -- Does it handle translation?\n\n## The Realization\nIteration is instant. No staring at a blank page. No \"let me think about this and come back tomorrow.\"\n\nYou can generate 10 variations in the time it takes to write one. Then pick the best parts from each.\n\n## Try Your Own\nWhat variation would be useful for your actual work? Type it in. See what happens.\n\nRemember: bad output is fine. You're exploring, not publishing."}, 15, 20, 4)

    await insert_lesson(m1_1, "The Three Questions", "article", {"body": "# The Three Questions\n\nThis is private reflection. Write your answers down. You will **not** be asked to share these unless you volunteer.\n\n## Question 1\n**What was easier than you expected?**\n\nMaybe the tool was simpler than you thought. Maybe the output was better than you feared. Maybe editing was faster than writing from scratch. Whatever it was -- name it.\n\n## Question 2\n**What would you never let AI touch?**\n\nThis isn't a trick question. There are things AI should not do for your library. Name them. Be specific.\n\nExamples from past sessions:\n- Responding to a patron complaint\n- Writing a letter of recommendation for a colleague\n- Deciding which programs to cut\n- Talking to a kid who's upset\n\n## Question 3\n**What surprised you?**\n\nGood or bad. Something you didn't expect going into today.\n\n## Keep These\nYour answers are yours. Bring them to Session 2 if you want. Or don't. No pressure."}, 15, 15, 5)

    await insert_lesson(m1_1, "The 'Never' List", "lab", {"body": "# The \"Never\" List\n\nThis is a group activity built from Question 2.\n\n## How It Works\n- Anyone who wants to share their \"never\" items writes them on sticky notes (one per note)\n- Post them on the wall\n- Group by theme\n\n## Common Themes\n- **Patron privacy** -- anything involving patron data, reading history, personal information\n- **Creative work** -- original programming ideas, collection philosophy, community voice\n- **Crisis response** -- patron emergencies, difficult conversations, safety decisions\n- **Legal matters** -- policy interpretation, ADA compliance, personnel issues\n- **Relationships** -- partner communications that require trust, board interactions, advocacy\n\n## The Frame\n> \"This isn't resistance. This is judgment. This is exactly what we need.\"\n\nSkepticism isn't a problem to overcome. It's professional expertise in action. The \"never\" list is the most important thing we build today.\n\n## Keep It\nThis list comes back in Session 2. It becomes the foundation of your AI use policy."}, 15, 20, 6)

    await insert_lesson(m1_1, "Homework: The Real Test", "article", {"body": "# Homework: The Real Test\n\nBetween now and Session 2, use the local LLM for **one real task** at work.\n\nNot a test. Not practice. A real thing you actually need to do.\n\n## Document Three Things\n1. **What you asked for** -- the actual prompt you typed\n2. **What you got** -- the AI's output (screenshot or copy-paste)\n3. **What you changed** -- your edits before using it\n\n## Rules\n- No required sharing. This is for your observation only.\n- If it doesn't work, that's useful data. Document the failure.\n- If you don't use it at all, that's also useful data. Write down why.\n\n## The Promise\n> \"Next session, we start with your real experiences. Not theory. Not demos. Your actual work.\"\n\nSee you at Session 2."}, 5, 10, 7)

    # Session 2: The Check-In
    m1_2 = await insert_module(c1, "Session 2: The Check-In", "Learn from real use, build institutional policy together. Two hours of honest assessment and co-created guidelines.", 1)

    await insert_lesson(m1_2, "The Check-In Round", "lab", {"body": "# The Check-In Round\n\n## How It Works\nVolunteer sharing only. Go around the room (or popcorn-style).\n\n## Share\n- What task did you try?\n- What worked?\n- What bombed?\n- What surprised you?\n\n## Facilitator Rules\n- **No correcting.** If someone says \"I couldn't figure out the prompt,\" don't say \"you should have tried X.\" Just ask: \"What did you try?\"\n- **No judgment.** If someone didn't use it at all, that's fine. Ask: \"What held you back?\"\n- **Just curiosity.** \"Tell me more about that\" is always the right response.\n\n## Capture\nDocument successes and failures on the shared board. Two columns:\n\n| Worked | Didn't Work |\n|--------|-------------|\n| (capture as people share) | (capture as people share) |\n\nThis board feeds into the next activity."}, 30, 20, 0)

    await insert_lesson(m1_2, "The Pattern Hunt", "lab", {"body": "# The Pattern Hunt\n\nLook at the shared board. What patterns emerge?\n\n## What Tasks Worked Well for AI?\nUsually:\n- First drafts of anything\n- Formatting and restructuring existing text\n- Brainstorming ideas and variations\n- Repetitive communication (similar emails, recurring posts)\n- Summarizing long documents\n- Translating tone (formal to casual, adult to kid-friendly)\n\n## What Tasks Failed?\nUsually:\n- Anything requiring emotional intelligence\n- Anything requiring community context (\"our patrons,\" \"our neighborhood\")\n- Crisis judgment calls\n- Nuanced policy interpretation\n- Anything where being wrong has real consequences\n\n## What Tasks Were Mixed?\nUsually:\n- Required heavy editing but saved some time\n- Needed fact-checking before use\n- Got the structure right but the voice wrong\n- Good starting point but needed local details added\n\n## The Insight\nAI is a first-draft machine. It's fast but generic. Your job is everything that makes it specific, accurate, and human.\n\n## Document\nWrite these three lists on the wall. They become your policy foundation."}, 30, 25, 1)

    await insert_lesson(m1_2, "Drafting AI Use Guidelines", "lab", {"body": "# Drafting AI Use Guidelines\n\n## The Exercise\nIn pairs, draft \"AI Use Guidelines\" for your library.\n\n## Must Include Four Sections\n\n### 1. What AI Can Do\nBased on today's evidence. Examples:\n- Generate first drafts of social media posts, newsletters, program descriptions\n- Brainstorm program ideas and themes\n- Reformat or restructure existing documents\n- Translate text between languages (with human review)\n- Summarize long documents or reports\n\n### 2. What AI Cannot Do\nBased on your \"Never\" list. Examples:\n- Make final decisions about patron services\n- Generate patron-facing content without staff review\n- Handle crisis response or safety situations\n- Interpret legal or policy questions\n- Replace professional judgment about collections or programming\n\n### 3. What Staff Must Always Do\n- Fact-check AI output before using it\n- Add your voice and local context\n- Take responsibility for the final product\n- Review for accuracy, tone, and appropriateness\n- Never share patron data with AI tools\n\n### 4. How to Explain AI Use to Patrons\nA simple, honest script:\n> \"I used a tool to help draft this, then reviewed and edited it to make sure it's accurate and sounds like us.\"\n\n## Time\n20 minutes to draft. Then we merge."}, 45, 30, 2)

    await insert_lesson(m1_2, "The Merge: Building Shared Policy", "lab", {"body": "# The Merge\n\n## How It Works\nEach pair shares their draft with the full group.\n\nThe facilitator captures common themes and synthesizes into a single document in real time.\n\n## The Vote\nEach person gets 3 dot stickers. Place them on the guidelines you feel **strongest** about -- the ones that absolutely must stay.\n\n## The Result\nA staff-authored, staff-approved AI use policy.\n\nNot handed down from administration. Not copied from another library. Not written by a consultant. Written by the people who will use it.\n\n## What Makes This Different\n- It's based on evidence from your own experience, not theory\n- It includes your professional judgment about boundaries\n- It will be posted, referenced, and updated by the people who wrote it\n- It's a living document -- change it when reality proves it wrong"}, 15, 20, 3)

    await insert_lesson(m1_2, "The Commitment and Next Steps", "article", {"body": "# The Commitment\n\n## Where the Policy Goes\n- Posted in the break room\n- At service desks\n- In the staff manual\n- Shared with anyone who asks \"does the library use AI?\"\n\n## What Makes This Work\nThis policy was **not imposed from above.** It was co-created, co-owned, and co-maintained by the people it affects.\n\n## The Maintenance Plan\n- Review quarterly: Is it still accurate? Has anything changed?\n- Update when someone finds a new use case or a new boundary\n- New staff read it during onboarding and add their input\n\n## The Invitation\n> \"This was Course 1. Course 2 is for when you're ready to prove the AI can't do your real job. No pressure. You're in charge of your pace.\"\n\n## Course 2: The Reference Interview vs. The Chatbot\n- 6 hours over 3 sessions\n- Tests AI against your actual reference skills\n- Spoiler: you win. But you'll understand exactly why.\n- Available when you're ready. No rush."}, 15, 15, 4)

    quiz1 = await insert_lesson(m1_2, "Session 2 Assessment", "quiz", {"body": "Reflection quiz on the full AI for the Exhausted course experience."}, 10, 25, 5)
    await insert_quiz(quiz1, "Based on your experience, which type of task is AI most useful for?", [{"text": "Making final decisions about patron services", "is_correct": False}, {"text": "Generating first drafts and brainstorming variations", "is_correct": True}, {"text": "Handling crisis situations with patrons", "is_correct": False}, {"text": "Interpreting library policies for edge cases", "is_correct": False}], "AI excels at generating first drafts, brainstorming, and creating variations. It's a starting point, not a decision-maker.", 0)
    await insert_quiz(quiz1, "What must staff ALWAYS do when using AI-generated content?", [{"text": "Post it immediately to save time", "is_correct": False}, {"text": "Ask a manager to approve it first", "is_correct": False}, {"text": "Review it for accuracy, add your voice, and take responsibility for the final product", "is_correct": True}, {"text": "Add a disclaimer that AI wrote it", "is_correct": False}], "Staff must always fact-check, add local context and voice, and take responsibility for anything that goes out with the library's name on it.", 1)
    await insert_quiz(quiz1, "A patron asks: 'Did a computer write this flyer?' What's the best response?", [{"text": "No, I wrote it myself.", "is_correct": False}, {"text": "I used a tool to help draft it, then reviewed and edited it to make sure it's accurate and sounds like us.", "is_correct": True}, {"text": "Yes, AI wrote it. We use AI for everything now.", "is_correct": False}, {"text": "I can't discuss our internal processes.", "is_correct": False}], "Transparency and ownership. You used a tool, you reviewed it, you stand behind it. Honest and simple.", 2)
    await insert_quiz(quiz1, "Why is the 'Never' list the most important output of this course?", [{"text": "It proves AI is useless", "is_correct": False}, {"text": "It represents professional judgment about where human skills are irreplaceable", "is_correct": True}, {"text": "It protects the library from lawsuits", "is_correct": False}, {"text": "Administration requires it for compliance", "is_correct": False}], "The 'Never' list isn't resistance -- it's professional expertise. Knowing what AI shouldn't do is as important as knowing what it can do.", 3)

    # ================================================================
    # COURSE 2: The Reference Interview vs. The Chatbot
    # ================================================================
    c2 = await insert_course(
        "The Reference Interview vs. The Chatbot",
        "Public services staff prove their irreplaceable skills through direct comparison with AI. Three sessions of head-to-head testing, local knowledge building, and hybrid workflow design. Spoiler: the librarian wins -- but you'll understand exactly why.",
        "staff", "intermediate", 360,
        "Roleplay activities in Session 3. Verbal sharing expected but can be written instead. Screen-based comparison work in Sessions 1-2.",
        350
    )

    # Session 1: The Turing Test
    m2_1 = await insert_module(c2, "Session 1: The Turing Test", "Establish irreplaceable human skills through direct comparison. Bring your real reference questions and watch the AI try to answer them.", 0)

    await insert_lesson(m2_1, "The Question Bank", "lab", {"body": "# The Question Bank\n\n## Preparation\nBring 3 real reference questions you've answered in the past month. Write them on index cards, anonymized (remove patron names or identifying details).\n\n## Examples of Good Questions to Bring\n- Factual lookups: \"When was our town founded?\"\n- Reader's advisory: \"My book club liked *Educated* -- what should we read next?\"\n- Research help: \"I need to find my grandmother's immigration records\"\n- Tech help: \"How do I get ebooks on my Kindle?\"\n- Local info: \"Where can I get my taxes done for free?\"\n\n## The Frame\n> \"These are your victories. Today we test whether a machine could have won.\"\n\nEvery question on these cards represents a moment where a patron needed help and you provided it. Today we find out what the AI would have done instead."}, 15, 15, 0)

    await insert_lesson(m2_1, "Round 1: Human vs. Machine", "lab", {"body": "# Round 1: Human vs. Machine\n\n## The Setup\nEach staff member picks one of their own reference questions.\n\n## Three Answers, One Question\n\n### Step 1: Your Answer (5 min)\nAnswer the question the way you actually answered it. Write it down -- include the sources you used, the follow-up you offered, the tone you struck.\n\n### Step 2: Local LLM (5 min)\nType the same question into the local LLM. Copy the response exactly.\n\n### Step 3: ChatGPT (5 min)\nSame question to ChatGPT (or equivalent cloud AI). Copy the response.\n\n## Side-by-Side Comparison\nEvaluate all three answers on 4 criteria:\n\n| Criteria | Your Answer | Local LLM | ChatGPT |\n|----------|------------|-----------|----------|\n| **Accuracy** | Is the answer correct? | | |\n| **Sources** | Does it cite where it got this? | | |\n| **Tone** | Does it match your library's voice? | | |\n| **Follow-up** | Does it anticipate the next question? | | |\n\n## Discussion\n- Where did AI compete with you?\n- Where did it fall flat?\n- Was there a difference between local and cloud AI?"}, 45, 30, 1)

    await insert_lesson(m2_1, "Round 2: The Trick Questions", "lab", {"body": "# Round 2: The Trick Questions\n\nThe facilitator introduces 3 questions that require **local knowledge** -- things no AI could know without being told.\n\n## The Questions\n\n### Question 1: Institutional Memory\n> \"Where's the quiet study space that isn't officially listed on the website?\"\n\nEvery library has one. The corner by the large print. The table behind the DVDs. Staff know. AI doesn't.\n\n### Question 2: Community Context\n> \"My kid loved the reptile program last year -- when's the next one?\"\n\nThis requires knowing your program history, your presenters, your calendar patterns. The AI will guess or hallucinate.\n\n### Question 3: Research Judgment\n> \"I'm researching my house's history -- where do I start?\"\n\nThis requires knowing your local history collection, county records office, historical society partnerships, and the order that actually works for your area.\n\n## Watch the AI Try\nType each question into the LLM. Observe what happens.\n\n## Discussion\n- What requires institutional memory?\n- What requires community trust?\n- What can only be learned by working here?"}, 30, 25, 2)

    await insert_lesson(m2_1, "The 10 Questions AI Can't Answer", "lab", {"body": "# The 10 Questions AI Can't Answer\n\nBased on today's evidence, brainstorm as a group.\n\n## Categories to Consider\n- **Local knowledge** -- things specific to your community, building, or collection\n- **Emotional nuance** -- when the question behind the question matters more than the question itself\n- **Crisis judgment** -- when safety or wellbeing is at stake\n- **Creative connection** -- when the answer is \"let me introduce you to someone\" or \"have you considered this angle?\"\n- **Relationship context** -- when the answer depends on knowing the patron\n\n## The List\nWrite your 10 questions on the board. These are your proof.\n\n## Deliverable\nPrint this list. Post it at the reference desk.\n\nNot as a trophy. As a reminder of what you do that no machine can replicate.\n\n## Homework\nBring one \"AI almost got it\" example next week -- where the machine was close but dangerously wrong. The near-misses are more important than the obvious failures."}, 20, 20, 3)

    quiz2_1 = await insert_lesson(m2_1, "Session 1 Check", "quiz", {"body": "Knowledge check for Session 1: The Turing Test"}, 10, 20, 4)
    await insert_quiz(quiz2_1, "When comparing AI answers to human answers, which criteria revealed the biggest gap?", [{"text": "Speed of response", "is_correct": False}, {"text": "Follow-up questions and anticipating patron needs", "is_correct": True}, {"text": "Formatting and grammar", "is_correct": False}, {"text": "Length of response", "is_correct": False}], "AI can be fast and well-formatted, but it consistently fails at anticipating follow-up needs -- the core of a good reference interaction.", 0)
    await insert_quiz(quiz2_1, "Why do 'trick questions' involving local knowledge matter?", [{"text": "They prove AI is always wrong", "is_correct": False}, {"text": "They demonstrate that institutional memory and community context are irreplaceable human skills", "is_correct": True}, {"text": "They're fun exercises with no practical value", "is_correct": False}, {"text": "They show we need better AI training data", "is_correct": False}], "Local knowledge isn't a gap in AI training -- it's a category of knowledge that requires being part of a community. That's your job.", 1)

    # Session 2: Training the Local Brain
    m2_2 = await insert_module(c2, "Session 2: Training the Local Brain", "Make the AI smarter about your patrons, not generic users. Feed it local knowledge and test whether it improves.", 1)

    await insert_lesson(m2_2, "Homework Share: The Almost Got It", "lab", {"body": "# Homework Share\n\n## The Question\nWho found an \"almost got it\" example -- where the AI was close but dangerously wrong?\n\n## Share\n- What was the question?\n- What did the AI say?\n- What was wrong with it?\n- What was the gap? Context? Timing? Tone? Privacy?\n\n## Why Near-Misses Matter\nObvious failures are easy to catch. A clearly wrong answer gets rejected immediately.\n\nBut when AI is *almost* right -- when it's 90% correct with a confident tone -- that's when people get hurt. A patron follows bad directions. A researcher cites a hallucinated source. A program gets the wrong date.\n\n## Capture\nDocument the near-misses on the board. These become your quality control checklist."}, 20, 15, 0)

    await insert_lesson(m2_2, "Feeding the Local Brain (RAG Basics)", "article", {"body": "# Feeding the Local Brain\n\n## The Concept (No Jargon)\nRight now, the AI knows what the internet knows. It doesn't know what *your library* knows.\n\nWe're going to give the AI a library card to **your** collection of knowledge.\n\n## What We're Doing\nWe're feeding local documents into the LLM so it can reference them when answering questions. Think of it this way:\n- **Before:** The AI is a smart stranger visiting your town\n- **After:** The AI is a smart stranger who read your library's staff manual\n\nIt still doesn't *understand* your community. But it has better source material.\n\n## What to Feed It\n\n| Document Type | Why It Helps |\n|--------------|-------------|\n| Policy documents | Answers policy questions accurately |\n| Community partner list | Knows who to refer patrons to |\n| Local history collection index | Can help with genealogy/local research |\n| FAQ log (real questions staff have answered) | Learns your most common interactions |\n| Program calendar and history | Knows what you've offered and when |\n| Building map / service descriptions | Knows where things are |\n\n## What NOT to Feed It\n- Patron records or reading history (privacy)\n- Personnel files (confidentiality)\n- Board meeting minutes with sensitive discussions\n- Anything you wouldn't post on a public bulletin board"}, 30, 25, 1)

    await insert_lesson(m2_2, "The Retest: Did Local Knowledge Help?", "lab", {"body": "# The Retest\n\n## Same Questions, Better Brain\nRe-run the \"trick questions\" from Session 1 against the locally-fed LLM.\n\n### Question 1: The Quiet Study Space\nDid it find the answer in your documents? Is the answer accurate?\n\n### Question 2: The Reptile Program\nDoes it know about your program history now? Does it give the right timeframe?\n\n### Question 3: House History Research\nCan it point to your local resources now? Does it know the right order of operations?\n\n## Score It\n\n| Question | Before (Session 1) | After (Local Feed) | Still Missing |\n|----------|--------------------|--------------------|---------------|\n| Quiet study space | | | |\n| Reptile program | | | |\n| House history | | | |\n\n## Discussion\n- What improved?\n- What still fails? Why?\n- What's newly possible that wasn't before?\n- Does \"better\" mean \"good enough to trust\"?"}, 30, 25, 2)

    await insert_lesson(m2_2, "The Gap Hunt", "lab", {"body": "# The Gap Hunt\n\n## What to Feed It Next?\nBased on the retest, what's still missing? Brainstorm as a group.\n\n## Format Questions\n- What file formats work? (PDFs? Spreadsheets? Emails? Web pages?)\n- How current does the information need to be?\n- Who owns keeping it updated? (This is the real question.)\n\n## The Maintenance Reality\nA knowledge base that isn't maintained is worse than no knowledge base. Outdated information from a \"trusted\" source is more dangerous than no information.\n\n## Assign Ownership\n\n| Document Type | Who Updates | How Often |\n|--------------|------------|----------|\n| Program calendar | | |\n| Community partners | | |\n| FAQ log | | |\n| Policy documents | | |\n\n## The Power Shift\n> \"Last week, the AI was a stranger. Now it works here. What changed?\"\n> \"Who controls what it knows?\"\n> \"What happens if we stop feeding it?\"\n\nYou control this. That's the point."}, 20, 20, 3)

    await insert_lesson(m2_2, "Homework: Add One Document", "article", {"body": "# Homework\n\nAdd **one document** to the local knowledge base before Session 3.\n\nPick something from the gap hunt list. Something you know is useful. Feed it in.\n\nNote what happens:\n- Did the AI's answers improve for questions related to that document?\n- Did anything unexpected change?\n- Was the process easy or painful?\n\nBring your observations to Session 3."}, 5, 10, 4)

    # Session 3: The Hybrid Model
    m2_3 = await insert_module(c2, "Session 3: The Hybrid Model", "Design workflows that combine AI speed with human judgment. Build the handoff protocols your library will actually use.", 2)

    await insert_lesson(m2_3, "Homework Check", "lab", {"body": "# Homework Check\n\n## Quick Round\n- What document did you add?\n- What changed in the AI's responses?\n- Any surprises?\n\nCapture useful findings on the board. This feeds into today's workflow design."}, 15, 10, 0)

    await insert_lesson(m2_3, "Scenario Mapping: 5 Common Situations", "lab", {"body": "# Scenario Mapping\n\nDesign workflows for 5 common patron interactions that combine AI speed with human judgment.\n\n## The Scenarios\n\n### Scenario 1: Reader's Advisory\n> Patron asks: \"I want books like [popular title]\"\n\n### Scenario 2: Genealogy Research\n> Patron says: \"I need help finding my grandmother's immigration records\"\n\n### Scenario 3: Controversial Topic\n> Patron asks about a politically sensitive subject\n\n### Scenario 4: Distress Indicator\n> Patron seems upset, mentions housing instability or food insecurity\n\n### Scenario 5: Room Reservation\n> Patron wants to reserve a meeting room for a recurring group\n\n## For Each Scenario, Map:\n\n1. **Does the patron interact with AI first?** (If ever)\n2. **When does staff take over?** What's the trigger?\n3. **What's the handoff signal?** How does the patron know they're talking to a person now?\n4. **How do we explain AI involvement?** Script it.\n5. **What gets documented?** For quality control and training.\n\n## Small Group Work\n2-3 people per scenario. 10 minutes each.\nShare back: 5 minutes per group.\n\n## Key Principle\nThe patron should never wonder if they're getting human attention. The handoff should be invisible or explicitly announced -- never ambiguous."}, 75, 40, 1)

    await insert_lesson(m2_3, "The Workflow Vote", "lab", {"body": "# The Workflow Vote\n\n## Post All 5 Workflows\nEach group posts their workflow diagram on the wall.\n\n## Dot Voting (3 rounds)\nEveryone gets 3 colored dots:\n- **Green:** This feels right. I'd use this tomorrow.\n- **Yellow:** This needs more thought. Not sure yet.\n- **Red:** This feels risky. I have concerns.\n\n## Capture Dissent\nThe facilitator's job is to **capture dissent, not resolve it.**\n\nDissent is data. If someone puts a red dot on Scenario 4 (distress indicator), that's important information. Ask why. Write it down. Don't argue.\n\n## Deliverable\nWorkflow diagrams, printed and posted at each service point.\n\n> \"These are living documents. Change them when reality proves them wrong.\""}, 20, 20, 2)

    await insert_lesson(m2_3, "Course Wrap-Up and Invitation", "article", {"body": "# Course Wrap-Up\n\n## What You Built\n- A comparison framework showing where AI competes and where it can't\n- A locally-trained knowledge base that knows your library\n- Workflow diagrams for 5 common scenarios\n- Evidence-based confidence in your irreplaceable skills\n\n## The Through-Line\n- **Course 1** taught you AI is a first-draft machine\n- **Course 2** proved your skills are irreplaceable -- and showed you where AI can amplify them\n- **Course 3** is for when you're ready to build something no vendor would sell you\n\n## The Invitation\n> \"Course 3 is for when you're ready to build a tool no vendor would sell us. It requires everything you've learned here.\"\n\n## Course 3: The Scanner & The Stack\n- 8 hours over 4 sessions\n- Build a legislation monitoring tool for challenged materials\n- Create a crisis response protocol\n- Connect with peer libraries for shared defense\n- Available when you're ready. No rush."}, 10, 15, 3)

    quiz2_3 = await insert_lesson(m2_3, "Final Assessment: Reference vs. Chatbot", "quiz", {"body": "Final assessment for Course 2"}, 10, 30, 4)
    await insert_quiz(quiz2_3, "What is the primary value of feeding local documents into an AI system?", [{"text": "It makes the AI as good as a human librarian", "is_correct": False}, {"text": "It gives the AI access to local context it otherwise wouldn't have, improving accuracy for institution-specific questions", "is_correct": True}, {"text": "It eliminates the need for staff to answer reference questions", "is_correct": False}, {"text": "It satisfies a technology requirement from administration", "is_correct": False}], "Local knowledge feeds improve accuracy for your specific context, but the AI still doesn't understand your community.", 0)
    await insert_quiz(quiz2_3, "In a hybrid workflow, when should a patron ALWAYS interact with a human instead of AI?", [{"text": "When they ask a simple factual question", "is_correct": False}, {"text": "When they show signs of distress or the situation requires emotional judgment", "is_correct": True}, {"text": "When they ask about library hours", "is_correct": False}, {"text": "When they want a book recommendation", "is_correct": False}], "Crisis situations, emotional needs, and anything requiring human judgment should always involve a person.", 1)
    await insert_quiz(quiz2_3, "What is the biggest risk of AI that is 'almost right'?", [{"text": "It wastes the patron's time", "is_correct": False}, {"text": "Its confident tone makes incorrect information seem trustworthy, leading patrons to act on bad information", "is_correct": True}, {"text": "It embarrasses the library", "is_correct": False}, {"text": "It uses too much electricity", "is_correct": False}], "Near-misses are more dangerous than obvious failures. A 90% correct answer delivered with confidence can send a patron down the wrong path.", 2)

    # ================================================================
    # COURSE 3: The Scanner & The Stack
    # ================================================================
    c3 = await insert_course(
        "The Scanner & The Stack",
        "Build defensive tools no vendor would sell you. Four sessions covering legislation monitoring, challenged materials alerts, crisis response protocols, and peer library networks. This is where staff stop using tools and start building defenses.",
        "staff", "advanced", 480,
        "Roleplay exercises in Session 3 may involve emotionally charged scenarios (censorship, patron distress). Content discusses book banning and intellectual freedom challenges.",
        500
    )

    # Session 1: The Threat Landscape
    m3_1 = await insert_module(c3, "Session 1: The Threat Landscape", "Understand why this tool must exist and why only you can build it.", 0)
    await insert_lesson(m3_1, "The Prompt: Values Under Pressure", "lab", {"body": "# The Prompt\n\n## The Question\n> \"Name a time you felt the library's values were under external pressure.\"\n\nWrite your answer on a card. No names, no details that identify specific people. Just the situation.\n\n## The Grouping\nPost cards on the wall. Group by theme:\n- **Funding pressure** -- threats to budgets tied to collection or programming decisions\n- **Censorship** -- demands to remove, relocate, or restrict materials\n- **Community conflict** -- organized opposition to programs or policies\n- **Vendor pressure** -- platforms or providers limiting what you can offer\n- **Policy changes** -- legislative or administrative actions that constrain library work\n\n## Why This Matters\nEvery card on that wall represents a moment where the library needed to defend its mission. Today we start building tools to see those moments coming."}, 20, 15, 0)
    await insert_lesson(m3_1, "The Legislation Hunt", "lab", {"body": "# The Legislation Hunt\n\n## The Task\nIn pairs, search current state legislation for bills that target library materials, programs, or operations.\n\n## What to Track\n\n| Field | What to Record |\n|-------|---------------|\n| Bill number | e.g., HB 1234, SB 567 |\n| Sponsor | Who introduced it |\n| Status | Committee, floor vote, signed, dead |\n| Targeted titles/themes | Specific books or broad categories |\n| Impact on libraries | Direct mandate, funding threat, criminal liability |\n\n## Free Sources\n- **LegiScan** (legiscan.com) -- free tier tracks bills by keyword\n- **State legislature website** -- every state has one, search by keyword\n- **PEN America** (pen.org/banned-books) -- tracks challenged and banned titles\n- **ALA Office for Intellectual Freedom** -- challenge database\n- **EveryLibrary** -- tracks library-specific legislation\n\n## The Constraint\nNo paid databases. Only what anyone can find for free."}, 40, 30, 1)
    await insert_lesson(m3_1, "The Cross-Reference", "lab", {"body": "# The Cross-Reference\n\n## The Moment of Truth\nTake 5 titles from the legislation you found -- books that are being targeted in bills.\n\nNow search your catalog:\n- Do you own them?\n- Where are they shelved?\n- What's their circulation?\n- Are any on hold right now?\n\n## The Realization\n> \"This book they're trying to ban? It's in our collection. Right now. Someone checked it out last Tuesday.\"\n\nThis isn't abstract. This isn't happening \"somewhere else.\" These bills target books on your shelves, used by your patrons."}, 30, 25, 2)
    await insert_lesson(m3_1, "The Vendor Question", "article", {"body": "# The Vendor Question\n\n## Three Questions\n\n### 1. Why doesn't your ILS vendor build this?\nYour integrated library system knows your catalog. State legislation is public data. The cross-reference is trivial to automate.\n\nSo why doesn't your vendor offer a \"challenged materials alert\" feature?\n\nBecause it's controversial. Vendors avoid controversy.\n\n### 2. What would happen if they did?\nThey'd water it down. They'd make it opt-in with so many disclaimers that nobody would use it.\n\n### 3. Why is this our responsibility?\nBecause vendors avoid controversy. Libraries can't.\n\n> \"Sovereignty means we don't need their permission to defend our mission.\"\n\n## Homework\nFind one more bill. Find one more book in your collection that it targets. Document both."}, 20, 20, 3)

    # Session 2: Build the Monitor
    m3_2 = await insert_module(c3, "Session 2: Build the Monitor", "Create a working alert system for challenged materials.", 1)
    await insert_lesson(m3_2, "Homework Share: Expanding the List", "lab", {"body": "# Homework Share\n\nQuick round: What did you find?\n- New bills?\n- New titles in your collection?\n- Any patterns emerging?\n\nAdd everything to the shared spreadsheet from Session 1."}, 15, 10, 0)
    await insert_lesson(m3_2, "Building the Scraper", "lab", {"body": "# Building the Scraper\n\n## What We're Building\nA script that checks 3 sources daily and flags anything relevant to your library.\n\n## The Sources\n1. **State legislature RSS feed**\n2. **PEN America banned book list**\n3. **Local news alerts**\n\n## The Tools\nPre-built script provided (Python or no-code tool like n8n).\n\n## Configuration Steps\n1. Add your state's legislature RSS URL\n2. Add keywords to watch\n3. Set notification preferences\n4. Test with a known bill from Session 1\n\n## Time\n30 minutes for setup. The facilitator walks through each step."}, 30, 35, 1)
    await insert_lesson(m3_2, "The Cross-Reference Engine", "lab", {"body": "# The Cross-Reference Engine\n\n## What It Does\nWhen the scraper finds a targeted title, it automatically checks your catalog export.\n\n## How It Works\n1. Export your catalog as CSV\n2. The script matches targeted titles against your catalog\n3. If there's a match: **ALERT**\n4. Output includes: title, author, shelf location, circulation count\n\n## The False Positive Problem\n- Same title, different book\n- Vague legislative language\n- Solution: Flag for human review, don't auto-escalate\n\n> \"Imperfect tools beat absent tools. Document limitations.\""}, 30, 35, 2)
    await insert_lesson(m3_2, "Setting Up Alerts", "lab", {"body": "# Setting Up Alerts\n\n## Where Do Alerts Go?\n- Email? Slack? Dashboard? Text?\n\n## Who Sees Them First?\nDesignate a primary responder. The goal is one person who triages, not everyone panicking.\n\n## The Escalation Path\n1. Alert fires\n2. Triage within 24 hours\n3. Assessment: is this real?\n4. Action: follow the response protocol (Session 3)\n\n## Homework\nLet the system run for one week. Document alerts and false positives."}, 25, 20, 3)
    await insert_lesson(m3_2, "The False Positive Discussion", "article", {"body": "# The False Positive Problem\n\nYour monitoring system will generate false positives. This is expected.\n\n## Why False Positives Are OK\nA false positive costs you 30 seconds of review. A missed alert costs you weeks of scrambling.\n\n## Tuning Over Time\n- Track false positive rate in the first month\n- Adjust keywords and matching rules\n- Never over-filter. Missing a real threat is worse than reviewing a false alarm.\n\n> \"Imperfect tools beat absent tools. Document limitations.\""}, 15, 15, 4)

    # Session 3: The Response Protocol
    m3_3 = await insert_module(c3, "Session 3: The Response Protocol", "Prepare for the moment the alert is real.", 2)
    await insert_lesson(m3_3, "The Scenario", "article", {"body": "# The Scenario\n\nYour alert system fires.\n\n> House Bill 123 targets *Gender Queer* by Maia Kobabe. You have it in YA.\n\nWhat happens in the next 24 hours?"}, 15, 10, 0)
    await insert_lesson(m3_3, "Roleplay: Four Perspectives", "lab", {"body": "# Roleplay: Four Perspectives\n\n## Role 1: The Director\nWhat's our legal exposure? What's our moral obligation?\n\n## Role 2: Public Services Staff\nWhat do I say when a patron asks about it?\n\n## Role 3: Board Member\nWhy are we involved in politics?\n\n## Role 4: Journalist\nCan you confirm you carry this book? What's your position?\n\n## Format\n- 5 minutes: preparation (in character)\n- 5 minutes: roleplay\n- 5 minutes: debrief"}, 45, 35, 1)
    await insert_lesson(m3_3, "Drafting the Response Protocol", "lab", {"body": "# Drafting the Response Protocol\n\n## Must Address\n- **Decision Authority:** Who decides?\n- **Public Statement:** Prepared or ad hoc? Who approves?\n- **Documentation:** What do we document? Where?\n- **Notification Chain:** Staff, board, peers, community, media\n- **Patron Communication:** Scripts for front-line, phone, social media\n\n## Time\n30 minutes. Write it down. This is your pre-commitment."}, 30, 30, 2)
    await insert_lesson(m3_3, "The Hard Questions", "lab", {"body": "# The Hard Questions\n\nNo resolution required. Just naming the tension.\n\n1. What if the director disagrees with the staff?\n2. What if the board orders removal?\n3. What if we're the only library in the state taking a stand?\n4. What if a staff member personally disagrees with keeping the book?\n\n> \"We decided this before the crisis. That's what makes it a principle, not a reaction.\"\n\n## Deliverable\nWritten protocol, dated, signed by participants."}, 20, 20, 3)

    # Session 4: The Network
    m3_4 = await insert_module(c3, "Session 4: The Network", "Connect with peer institutions for solidarity and shared defense.", 3)
    await insert_lesson(m3_4, "The Isolation Check", "lab", {"body": "# The Isolation Check\n\n> \"How many of you feel alone in this work?\"\n> \"How many know what the library 50 miles away is doing?\""}, 20, 15, 0)
    await insert_lesson(m3_4, "The Peer Map", "lab", {"body": "# The Peer Map\n\nIdentify 5 libraries in your region. Research each: Are they running similar tools? Facing similar threats?\n\nDraft a simple outreach email. Goal: One confirmed peer connection by end of session."}, 30, 25, 1)
    await insert_lesson(m3_4, "The Trust Layer: What to Share", "lab", {"body": "# The Trust Layer\n\n## What Can We Safely Share?\n- Titles being challenged, legislation tracked, response strategies, monitoring tools\n\n## What Must Stay Local?\n- Patron data, internal staff disagreements, pre-public board deliberations\n\n## How Do We Share Without Centralizing Vulnerability?\n- Distributed: each library runs own system, shares findings\n- Consortium: regional system hosts shared monitoring\n- Informal: regular check-in calls, shared documents\n\nShare knowledge. Protect specifics. Trust is built incrementally."}, 20, 20, 2)
    await insert_lesson(m3_4, "The Expansion Brainstorm", "lab", {"body": "# The Expansion Brainstorm\n\nWhat else should we monitor?\n- Curriculum challenges in local schools\n- Database/resource funding threats\n- Program opposition\n- Staff safety and intimidation\n\nDot vote: Which would you monitor next?\n\nThe pattern is the same: identify sources, build scraper, cross-reference locally, alert, follow protocol."}, 20, 20, 3)
    await insert_lesson(m3_4, "The Sovereignty Check", "article", {"body": "# The Sovereignty Check\n\n## Three Final Questions\n\n1. **What have we built that a vendor couldn't take away?** A monitoring system on your own infrastructure. Workflows designed by the people who do the work. A network of peer libraries.\n\n2. **What have we learned that a webinar couldn't teach?** That your professional judgment is irreplaceable. That building is different from buying.\n\n3. **What have we committed to that a policy memo couldn't enforce?** A co-created use policy. A crisis response protocol. A peer network. A maintenance plan."}, 20, 20, 4)
    await insert_lesson(m3_4, "The Graduation", "article", {"body": "# The Graduation\n\nNo certificates. No badges. Just this:\n\n> \"You built a defensive tool. You wrote a crisis protocol. You joined a network. You're not waiting for rescue. You're the rescue.\"\n\n## The Maintenance Plan\n- **Monthly:** Check alerts, update legislation tracker\n- **Quarterly:** Review protocol with new staff, update knowledge base\n- **Annually:** Reconvene full group, assess what's changed\n\n## The Three-Course Arc\n\n| Course | You Started As | You Left As |\n|--------|---------------|------------|\n| AI for the Exhausted | Skeptical, overworked | Someone with one useful AI habit and a co-authored policy |\n| Reference vs. Chatbot | Worried about replacement | Confident in irreplaceable skills, with hybrid workflows |\n| The Scanner & The Stack | Ready to build | Builder of defensive tools, member of a peer network |"}, 10, 25, 5)

    quiz3 = await insert_lesson(m3_4, "Final Assessment: The Scanner & The Stack", "quiz", {"body": "Final assessment for Course 3"}, 10, 35, 6)
    await insert_quiz(quiz3, "Why don't major ILS vendors build challenged materials monitoring tools?", [{"text": "The technology is too complex", "is_correct": False}, {"text": "There's no demand for it", "is_correct": False}, {"text": "It's controversial, and vendors avoid features that could alienate parts of their customer base", "is_correct": True}, {"text": "Libraries already have adequate tools for this", "is_correct": False}], "Vendors sell across the political spectrum. A feature designed to defend challenged materials would alienate some customers.", 0)
    await insert_quiz(quiz3, "What is the correct response when your monitoring system generates a false positive?", [{"text": "Disable the alert to reduce noise", "is_correct": False}, {"text": "Review it, document it, and adjust matching rules -- but never over-filter", "is_correct": True}, {"text": "Escalate immediately to the director", "is_correct": False}, {"text": "Remove the flagged title from the catalog as a precaution", "is_correct": False}], "False positives cost 30 seconds of review. Missed alerts cost weeks of scrambling.", 1)
    await insert_quiz(quiz3, "What makes a crisis response protocol effective?", [{"text": "It was written by the library's lawyer", "is_correct": False}, {"text": "It was decided before the crisis, by the people who will use it, as a pre-commitment", "is_correct": True}, {"text": "It guarantees the library will never face criticism", "is_correct": False}, {"text": "It delegates all decisions to the board", "is_correct": False}], "A protocol decided before the crisis is a principle. One written during the crisis is a reaction.", 2)
    await insert_quiz(quiz3, "When sharing information with peer libraries, what must always stay local?", [{"text": "The titles being challenged", "is_correct": False}, {"text": "Your monitoring tool configuration", "is_correct": False}, {"text": "Patron data, internal staff disagreements, and pre-public board deliberations", "is_correct": True}, {"text": "Your response strategies", "is_correct": False}], "Share knowledge freely. Protect patron privacy, internal deliberations, and personnel matters.", 3)

    # ================================================================
    # COURSE 4: Placement Survey
    # ================================================================
    c4 = await insert_course(
        "AI Training Placement: Where Are You Starting?",
        "A short self-assessment to help you find the right starting course in the AI training series. No right answers -- just honest reflection about where you are right now.",
        "staff", "beginner", 15, None, 25
    )

    m4 = await insert_module(c4, "Self-Assessment", "Answer honestly. This helps us place you where you'll learn best, not where we think you 'should' be.", 0)

    q4_1 = await insert_lesson(m4, "Your Relationship with AI", "quiz", {"body": "# Your Current Relationship with AI\n\nAnswer honestly. There are no right or wrong answers."}, 5, 10, 0)
    await insert_quiz(q4_1, "When someone mentions 'AI' at work, I feel:", [{"text": "Curious -- I want to know more", "is_correct": True, "weight": 5}, {"text": "Tired -- not another thing to learn", "is_correct": True, "weight": 1}, {"text": "Anxious -- what does this mean for my job?", "is_correct": True, "weight": 2}, {"text": "Angry -- this is being pushed on us", "is_correct": True, "weight": 1}, {"text": "Nothing -- it doesn't affect me", "is_correct": True, "weight": 3}], "All responses are valid. This helps us find the right starting point for you.", 0)
    await insert_quiz(q4_1, "I've used an AI tool (ChatGPT, Copilot, etc.) for work:", [{"text": "Never", "is_correct": True, "weight": 1}, {"text": "Once, didn't stick", "is_correct": True, "weight": 2}, {"text": "Occasionally", "is_correct": True, "weight": 3}, {"text": "Regularly", "is_correct": True, "weight": 4}, {"text": "Daily", "is_correct": True, "weight": 5}], "Never or once? Start with Course 1. Occasionally or more? You may be ready for Course 2.", 1)
    await insert_quiz(q4_1, "My biggest concern about AI in libraries is:", [{"text": "It will replace staff", "is_correct": True, "weight": 1}, {"text": "It will make mistakes we can't catch", "is_correct": True, "weight": 2}, {"text": "It's another thing to learn when we're already overwhelmed", "is_correct": True, "weight": 1}, {"text": "Vendors will use it to charge us more", "is_correct": True, "weight": 4}, {"text": "I don't have a concern", "is_correct": True, "weight": 5}], "Every concern here is legitimate.", 2)

    q4_2 = await insert_lesson(m4, "Your Technical Comfort", "quiz", {"body": "# Your Technical Comfort\n\nThis isn't a test of what you 'should' know."}, 4, 10, 1)
    await insert_quiz(q4_2, "When software breaks, I:", [{"text": "Call IT immediately", "is_correct": True, "weight": 1}, {"text": "Try restarting first", "is_correct": True, "weight": 2}, {"text": "Google the error message", "is_correct": True, "weight": 3}, {"text": "Dig into settings and logs", "is_correct": True, "weight": 4}, {"text": "Fix it and tell no one", "is_correct": True, "weight": 5}], "There's no wrong answer here.", 0)
    await insert_quiz(q4_2, "The phrase 'command line' makes me feel:", [{"text": "Terrified", "is_correct": True, "weight": 1}, {"text": "Uncomfortable", "is_correct": True, "weight": 2}, {"text": "Neutral", "is_correct": True, "weight": 3}, {"text": "Curious", "is_correct": True, "weight": 4}, {"text": "At home", "is_correct": True, "weight": 5}], "Course 3 involves some technical building.", 1)
    await insert_quiz(q4_2, "I've taught a colleague a tech skill:", [{"text": "Never", "is_correct": True, "weight": 1}, {"text": "Once", "is_correct": True, "weight": 2}, {"text": "A few times", "is_correct": True, "weight": 3}, {"text": "Regularly", "is_correct": True, "weight": 4}, {"text": "I train others officially", "is_correct": True, "weight": 5}], "Teaching experience correlates with readiness to build.", 2)

    q4_3 = await insert_lesson(m4, "Your Institutional Context", "quiz", {"body": "# Your Institutional Context"}, 3, 10, 2)
    await insert_quiz(q4_3, "My library's current AI approach is:", [{"text": "No policy, no discussion", "is_correct": True, "weight": 1}, {"text": "Some staff experimenting on their own", "is_correct": True, "weight": 2}, {"text": "Leadership is exploring vendor solutions", "is_correct": True, "weight": 3}, {"text": "We have approved tools in use", "is_correct": True, "weight": 4}, {"text": "We're building our own solutions", "is_correct": True, "weight": 5}], "If your library has no policy yet, Course 1's co-created policy exercise is especially valuable.", 0)
    await insert_quiz(q4_3, "When vendors pitch your library, you feel:", [{"text": "Excited -- new tools!", "is_correct": True, "weight": 3}, {"text": "Skeptical -- what's the catch?", "is_correct": True, "weight": 4}, {"text": "Resigned -- we'll probably buy it", "is_correct": True, "weight": 2}, {"text": "Angry -- not this again", "is_correct": True, "weight": 1}, {"text": "Empowered -- we can evaluate and say no", "is_correct": True, "weight": 5}], "Skeptical or resigned? Course 3's sovereignty thread speaks directly to vendor dependence.", 1)
